def group_by(items, key):
    groups = {}
    for item in items:
        if key not in item:
            continue
        groups.setdefault(item[key], []).append(item)
    return groups

def leaderboard(scores):
    pairs = [(name, round(sum(s) / len(s), 1)) for name, s in scores.items() if s]
    return sorted(pairs, key=lambda pair: (-pair[1], pair[0]))

