class Book:
    def __init__(self, title, author, pages):
        self.title = title
        self.author = author
        self.pages = pages

    def is_long(self):
        return self.pages > 300

    def __repr__(self):
        return f'Book({self.title!r}, {self.author!r})'

class Library:
    def __init__(self):
        self.books = {}

    def add(self, title):
        self.books[title] = False

    def borrow(self, title):
        if title not in self.books:
            raise KeyError(title)
        if self.books[title]:
            raise ValueError('already borrowed')
        self.books[title] = True

    def give_back(self, title):
        self.books[title] = False

    def available(self):
        return sorted(t for t, out in self.books.items() if not out)

