def averages_from_text(text):
    book = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        name, score = line.split(',')
        try:
            value = int(score)
        except ValueError:
            continue
        book.setdefault(name, []).append(value)
    return {name: round(sum(s) / len(s), 1) for name, s in book.items()}

import json

def report_json(averages, passing):
    values = list(averages.values())
    report = {
        'passed': sorted(n for n, a in averages.items() if a >= passing),
        'failed': sorted(n for n, a in averages.items() if a < passing),
        'class_average': round(sum(values) / len(values), 1) if values else None,
    }
    return json.dumps(report, ensure_ascii=False)
